import { SearchState } from '../newtab/features/searchForm/slice/types';
import { getOS, isSameDay, toDayFormat } from '../shared';

import {
  createNewTab,
  getStorageItems,
  removeTab,
  setStorageItems,
  updateTab,
} from '../shared/chromeApi';
import {
  getNumberTypeCookie,
  getOhCookie,
  setOhCookies,
} from '../shared/cookie';

import { ContentAds } from '../content/annotations/interfaces';
import { UserState } from '../newtab/features/user/slice/types';
import { GlobalState } from '../newtab/types.global';
import { createUserId } from '../shared';

const APP_URL = process.env.APP_URL;
let isAutofocus;
const APP_TYPE = process.env.APP_TYPE;
const APP_PLATFORM = process.env.APP_PLATFORM;

const openNtp = async (senderId) => {
  await createNewTab('chrome://newtab');
  await new Promise((resolve) => setTimeout(resolve, 500));
  await removeTab(senderId);
};

const updateShellsCounter = async (gain) => {
  const cookieCounter = await getNumberTypeCookie('shellsCounter');
  const newCounter = (cookieCounter || 0) + gain;
  setOhCookies('shellsCounter', newCounter);
};

const incrementContentAdClick = async () => {
  const storage = await getStorageItems < { contentAds: ContentAds } > ([
    'contentAds',
  ]);
  const contentAds = storage.contentAds || ({} as ContentAds);
  const { clicksPerDay } = contentAds;

  const counter =
    !clicksPerDay?.counter || !isSameDay(clicksPerDay.when)
      ? 0
      : clicksPerDay.counter;

  await setStorageItems({
    contentAds: {
      ...contentAds,
      clicksPerDay: { counter: counter + 1, when: Date.now() },
    },
  });
};

const onMessage = (request, sender, sendResponse) => {
  // console.log('MESSAGE: ', request);

  if (request.type === 'addShells') {
    // Add 50 shells
    chrome.cookies.get(
      {
        url: 'https://oceanhero.today',
        name: 'shellsCounter',
      },
      function (cookie) {
        const shells = cookie ? parseInt(cookie.value) : 0;
        chrome.cookies.set({
          url: 'https://oceanhero.today',
          name: 'shellsCounter',
          value: (shells + request.amount).toString(),
        });
      }
    );
  }

  if (request.type === 'setNtpSearchBoxFocus') {
    isAutofocus = request.payload;
    sendResponse({ success: true });
    return true;
  }

  if (request.type === 'contentAdClicked') {
    updateShellsCounter(request.gain).then(() => {
      sendResponse({ type: 'success' });
    });
    incrementContentAdClick();

    return true;
  }

  if (request.type === 'shellsCounter') {
    getOhCookie('shellsCounter')
      .then((shellsCounter) => {
        sendResponse({
          type: 'success',
          shellsCounter: Number(shellsCounter) || 0,
        });
      })
      .catch(() => {
        sendResponse({ type: 'failure', shellsCounter: null });
      });

    return true;
  }

  if (request === 'state') {
    getStorageItems().then((data) => {
      sendResponse({ type: 'success', data });
    });
    return true;
  }

  sendResponse({ success: true });
  if (['ntp'].includes(request)) openNtp(sender.tab.id);
  if (request === 'closeTab') removeTab(sender.tab.id);

  if (request.type === 'switchTo') {
    Promise.all([
      updateTab(request.tabId, { active: true }),
      removeTab(sender.tab.id),
    ]);
  }

  if (request.type === 'trackAnalytics') {
    if (request.events[0].payload[0] === 'Google_shells_disabled') {
      chrome.tabs.create({
        url: `https://docs.google.com/forms/d/e/1FAIpQLSdIttS4xOnSHUSaVHb1Q4q_MvrHB06tRzR4gDMFDSrYx-uLbg/viewform?usp=sf_link`,
        active: true,
      });
    }
  }

  if (request.type === 'openTab') {
    createNewTab(request.url);
  }
};

chrome.runtime.onMessageExternal.addListener(onMessage);
chrome.runtime.onMessage.addListener(onMessage);

const browserName = process.env.TARGET_BROWSER || 'chrome';

const TRACKING_QUERY = {
  browser: browserName.slice(0, 1).toUpperCase() + browserName.slice(1),
  redirect: 'true',
  extensionVersion: process.env.APP_VERSION,
  type: process.env.APP_TYPE,
  utm_medium: process.env.APP_TYPE === 'lite' ? 'ExtensionLite' : 'Extension',
};

const setUninstallUrl = (userId) => {
  const query = new URLSearchParams({ userId, ...TRACKING_QUERY });

  chrome.runtime.setUninstallURL(
    `${process.env.APP_URL}/api/uninstall?${query}`
  );
};

const getUserId = async (user) => {
  const userId = await getOhCookie('OH_USER_ID').catch(() => null);
  return userId || user?.userId || createUserId();
};

const saveIpAddressAndCountryCode = async () => {
  const ip = await fetch('https://api.ipify.org?format=json')
    .then((res) => res.json())
    .then((json) => json.ip)
    .catch(() => null);

  // Also get the country code from the IP
  const countryCode = await fetch(`https://ipapi.co/${ip}/country/`)
    .then((res) => res.text() || 'US')
    .catch(() => 'US');

  chrome.storage.local.set({ ip });
  chrome.storage.local.set({ countryCode });
};

const saveAnnotationsDomains = async () => {
  const response = await fetch(`${APP_URL}/annotations.json`);
  const kelkooMerchants = await fetch(`${APP_URL}/merchants.json`);

  if (!response.ok || !kelkooMerchants.ok) return;

  const json = await response.json();
  const merchants = await kelkooMerchants.json();

  const kelkooDomains = merchants
    .filter((merchant) => merchant.directoryLinks[0]?.urlTemplate)
    .map((merchant) =>
      merchant.directoryLinks[0]?.urlTemplate
        ?.replace('*', '')
        ?.replace('https://', '')
        ?.replace('http://', '')
    );

  chrome.storage.local.set({
    annotations: {
      ...json,
      kelkoo: kelkooDomains,
    },
  });
};

const savePartnersConfig = async () => {
  const response = await fetch(`${APP_URL}/api/partners`);

  if (!response.ok) return;

  const json = await response.json();

  chrome.storage.local.set({ partnersConfig: json });
};

const getNewTabUrl = () => `chrome-extension://${chrome.runtime.id}/index.html`;

const onInstalled = async (details) => {
  chrome.alarms.create('annotations', { periodInMinutes: 1440 }); // once every 24 hours
  chrome.alarms.create('partnersConfig', { periodInMinutes: 1440 }); // once every 24 hours
  await saveIpAddressAndCountryCode();
  saveAnnotationsDomains();
  savePartnersConfig();

  (async () => {
    const storage = await getStorageItems < GlobalState > (['user']);
    const user = storage.user || ({} as UserState);
    user.installationDate = user.installationDate || Date.now();
    user.userId = await getUserId(user);

    setUninstallUrl(user.userId);

    const date = new Date(user.installationDate);
    const extensionInstallDate = toDayFormat(date).split('-').join('');
    [
      ['OH_USER_ID', user.userId],
      ['Extension_User', `${APP_PLATFORM}_${APP_TYPE}_${extensionInstallDate}`],
      ['Extension_Install_Date', extensionInstallDate],
    ].map(([name, value]) => setOhCookies(name, value));

    if (details.reason === 'install') {
      const os = await getOS();
      if (
        os === 'Chrome OS' &&
        process.env.APP_TYPE !== 'lite' &&
        process.env.TARGET_BROWSER !== 'firefox' &&
        process.env.TARGET_BROWSER !== 'safari'
      ) {
        createNewTab(process.env.APP_URL);
      }

      const FIRST_RUN_PAGE = `${process.env.APP_URL
        }/api/install?${new URLSearchParams({
          ...TRACKING_QUERY,
          appUrl: APP_URL,
          userId: user.userId,
        })}`;

      if (
        process.env.TARGET_BROWSER !== 'firefox' &&
        process.env.TARGET_BROWSER !== 'safari'
      ) {
        createNewTab(FIRST_RUN_PAGE);
      }
    }

    const inviterId = await getOhCookie('inviterId').catch(() => null);

    user.isInvited = user.isInvited === null ? !!inviterId : user.isInvited;

    await setStorageItems({ user });
  })();
};

const onActionClick = () => {
  (async () => {
    await createNewTab('chrome://newtab');
  })();
};

const onAlarm = (alarm) => {
  if (alarm?.name === 'annotations') {
    saveAnnotationsDomains();
  }

  if (alarm?.name === 'partnersConfig') {
    savePartnersConfig();
  }
};

const createdTabsIds = [];

const onCreated = (tab) => {
  if (createdTabsIds.includes(tab.id)) return null;

  (async () => {
    if (typeof isAutofocus === 'undefined') {
      const storage = (await getStorageItems(['search'])) as {
        search: SearchState;
      };
      isAutofocus = storage.search?.isAutofocus;
    }
  })();

  if (isAutofocus) {
    // if (isAutofocus && tab.pendingUrl?.match('chrome://newtab')) {
    chrome.tabs.create(
      { url: `${getNewTabUrl()}?focus=true`, active: true },
      (newTab) => {
        createdTabsIds.unshift(newTab.id);
        createdTabsIds.splice(100); // just so array doesn't grow indefinitely

        chrome.tabs.remove(tab.id);
        chrome.tabs.update(newTab.id, { url: 'chrome://newtab/' });
      }
    );
  }
};

let isOpeningMyTab;

self.addEventListener('fetch', (e: any) => {
  const { url } = e.request;
  if (url.startsWith(location.origin + '/index.html') && !url.match('focus')) {
    isOpeningMyTab = true;
    setTimeout(() => {
      isOpeningMyTab = false;
    }, 50);
  }
});

chrome.alarms.onAlarm.addListener(onAlarm);

chrome.runtime.onInstalled.addListener(onInstalled);

// MV3
chrome.action.onClicked.addListener(onActionClick);
// chrome.browserAction.onClicked.addListener(onActionClick);

// -----------------------------------------------------------------------------

chrome.tabs.onCreated.addListener((tab) => {
  if (isOpeningMyTab) {
    // console.log('onCreated');
    onCreated(tab);
  }

  isOpeningMyTab = false;
});

self.addEventListener('push', (event: any) => {
  let data: any = {};
  // console.log('event', event);
  // @ts-ignore
  // console.log('event', event.data);
  if (event.data) {
    // @ts-ignore
    data = event.data.json();
    // console.log('data', data);
  }

  // @ts-ignore
  return self.registration.showNotification(data.authorName, {
    body: data.text,
    icon: 'img/icon128.png',
    data,
  });
});

self.addEventListener(
  'notificationclick',
  (event: any) => {
    // console.log('notificationclick', event);
    // console.log('notificationclick event.notification', event.notification);
  },
  false
);

chrome.commands?.onCommand.addListener((command) => {
  // console.log(`Command "${command}" triggered`);

  if (command === 'open-tab') {
    chrome.tabs.getCurrent((tab) => {
      chrome.tabs.create(
        {
          url: `chrome-extension://${chrome.runtime.id}/index.html?focus=shortcut`,
          active: true,
        },
        () => {
          // console.log('tab?.url', tab?.url);

          if (tab?.url?.startsWith('chrome-extension')) {
            chrome.tabs.remove(tab.id);
          }
        }
      );
    });
  }
});

// -----------------------------------------------------------------------------

(async () => {
  const storage = await getStorageItems < GlobalState > (['user', 'search']);
  isAutofocus = storage.search?.isAutofocus;

  const query = new URLSearchParams({
    ...TRACKING_QUERY,
    ...(storage?.user && { userId: storage.user.userId }),
  });

  chrome.runtime.setUninstallURL(
    `${process.env.APP_URL}/api/uninstall?${query}`
  );

  if (storage?.user?.userId) {
    setUninstallUrl(storage.user.userId);
  }
})();
